#include <map>
int main() {
  std::map<int, int> values;
  const int key = -13;
  int& original = values[key];
  if (original != 0 || values.size() != 1) return 1;
  original = 29;
  values[81] = 17;
  values[23] = 5;
  values[-40] = -8;
  values[-7] = 88;
  return values.size() != 5 || &values[key] != &original ||
         values[key] != 29 || values[23] != 5 || values[-7] != 88;
}

