const Pair& input(const Pair& pair) { trace = trace * 10 + 2; return pair; }
int main() {
  Map values;
  const Pair pair{8, 20};
  auto result = owner(values)->insert(input(pair));
  return trace != 12 || !result.second || result.first->second != 20 || values.size() != 1;
}

